/* Kish Team Goals | operational UI on existing records, no duplicate data store. */
(()=>{'use strict';
const f={status:'active',time:'all',results:'all',sort:'latest',show:true,q:'',teamq:'',expanded:new Set()};
const X=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=v=>v===null||v===undefined?'—':new Intl.NumberFormat('fa-IR',{useGrouping:false,maximumFractionDigits:1}).format(v);
const date=v=>{if(!v)return '—';let d=new Date(String(v).slice(0,10)+'T12:00:00Z');return Number.isNaN(+d)?'—':new Intl.DateTimeFormat('fa-IR',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}).format(d)};
const url=v=>encodeURIComponent(String(v||''));
const tr=(a,b)=>document.documentElement.lang==='en'?b:a;
const num=v=>v===null||v===undefined||v===''?null:Number.isFinite(Number(v))?Number(v):null;
const pct=k=>{let [a,b,c]=[num(k.baseline),num(k.current),num(k.target)];return a===null||b===null||c===null||a===c?null:Math.round(Math.max(0,Math.min(100,(b-a)/(c-a)*100)))};
const progress=g=>{let r=(g.krs||[]).map(pct).filter(v=>v!==null);return r.length?Math.round(r.reduce((a,b)=>a+b,0)/r.length):null};
const history=(data,id)=>data.history.filter(h=>h.krId===id).sort((a,b)=>String(b.at).localeCompare(String(a.at)));
function health(g,data){
 if(g.status==='closed')return ['closed',tr('مختومه','Closed')];
 let rs=(g.krs||[]).map(k=>({k,h:history(data,k.id)[0]})).filter(x=>x.h||x.k.lastUpdate);
 if(!rs.length)return ['none',tr('بدون وضعیت','No status')];
 let hs=rs.map(x=>x.h?.confidence||x.k.confidence);
 if(hs.includes('off-track'))return ['off',tr('خارج از مسیر','Off track')];
 if(hs.includes('attention'))return ['attention',tr('نیازمند توجه','Needs attention')];
 if(hs.includes('on-track'))return ['on',tr('روی مسیر','On track')];
 return ['none',tr('بدون وضعیت','No status')];
}
const khealth=k=>{let v=num(k.current),t=num(k.target);return v===null||t===null?['none',tr('فاقد داده','Missing')]:((k.direction==='down'?v<=t:v>=t)?['on',tr('مطلوب','Healthy')]:['attention',tr('نامطلوب','Unhealthy')])};
const badge=(h)=>'<span class="kt-badge kt-'+h[0]+'"><i></i>'+X(h[1])+'</span>';
function avatar(p){let photo=p?.photoUrl||p?.avatarUrl||p?.photo||'',name=p?.name||'؟';return '<i class="kt-avatar">'+(/^https:\/\//.test(photo)?'<img src="'+X(photo)+'" loading="lazy" alt="">':X(name.slice(0,2)))+'</i>';}
function person(name,d){let p=d.people.find(p=>[p.id,p.name,p.email].includes(name));let title=p?.name||name||tr('بدون مسئول','Unassigned');return '<a class="kt-owner" href="#people/'+url(p?.id||name)+'">'+avatar({name:title,...p})+'<span>'+X(title)+'</span></a>';}
function cyIndex(d){let m=new Map();d.cycles.forEach(c=>(c.goalIds||[]).forEach(id=>{if(!m.has(id))m.set(id,c)}));return m;}
const findUnit=(d,uid)=>d.units.find(x=>x.id===uid||x.orgChartId===uid)||{id:'company',name:tr('سطح شرکت','Company'),descendantIds:[]};
const scoped=(d,uid)=>uid==='company'?{goals:d.goals,kpis:d.kpis}:d.scopes[uid]||{goals:[],kpis:[]};
function filtered(d,uid){let m=cyIndex(d),goals=scoped(d,uid).goals.filter(g=>(f.status==='all'||(g.status||'draft')===f.status)&&(f.time==='all'||m.get(g.id)?.id===f.time)&&(!f.q||[g.objective,g.owner,g.why].join(' ').toLowerCase().includes(f.q.toLowerCase())));
 const recent=g=>(g.krs||[]).map(k=>k.lastUpdate||'').sort().at(-1)||'';
 goals.sort((a,b)=>f.sort==='title'?String(a.objective).localeCompare(b.objective,'fa'):f.sort==='progress'?(progress(b)??-1)-(progress(a)??-1):f.sort==='health'?(['off','attention','none','on'].indexOf(health(a,d)[0])-['off','attention','none','on'].indexOf(health(b,d)[0])):f.sort==='owner'?String(a.owner).localeCompare(String(b.owner),'fa'):f.sort==='time'?String(m.get(b.id)?.start||'').localeCompare(String(m.get(a.id)?.start||'')):recent(b).localeCompare(recent(a)));
 return {goals,m};}
function teamNav(d,uid){let children=new Map();d.orgChart.forEach(n=>{const id=n.parentId||'root';children.set(id,[...(children.get(id)||[]),n])});
 const rec=(n,depth)=>{if(depth>16)return '';let name=n.name||'',sub=(children.get(n.id)||[]).map(c=>rec(c,depth+1)).join('');if(f.teamq&&!name.toLowerCase().includes(f.teamq.toLowerCase())&&!sub)return '';let s=d.scopes[n.teamId]?.goals?.length||0;return '<div class="kt-tree-item kt-indent-'+Math.min(depth,5)+'"><a class="'+(n.teamId===uid?'active':'')+'" href="#team/'+url(n.teamId)+'/goals"><i class="kt-dot kt-c'+depth%5+'">'+X(name.slice(0,1))+'</i><span>'+X(name)+'</span><small>'+N(s)+'</small></a>'+sub+'</div>'};
 return '<aside class="kt-side"><h2>🏢 '+tr('تمام واحدها','All teams')+'</h2><input type="search" data-kt-teamq value="'+X(f.teamq)+'" placeholder="'+tr('جست‌وجوی واحد…','Search teams…')+'"><a class="kt-company" href="#team/company/goals">'+tr('سطح شرکت','Company')+'</a><div class="kt-tree">'+d.orgChart.filter(n=>!n.parentId||!d.orgChart.some(p=>p.id===n.parentId)).map(n=>rec(n,0)).join('')+'</div></aside>';}
function score(d,goals){let h={on:0,off:0,attention:0,none:0,closed:0};goals.forEach(g=>{if(g.status==='closed')h.closed++;else if(g.status==='active')h[health(g,d)[0]]++});let ps=goals.filter(x=>x.status==='active').map(progress).filter(x=>x!==null),avg=ps.length?Math.round(ps.reduce((a,b)=>a+b,0)/ps.length):null;
 return '<div class="kt-score"><div class="kt-statuses">'+[['on','روی مسیر'],['attention','نیازمند توجه'],['off','خارج از مسیر'],['none','بدون وضعیت'],['closed','مختومه']].map(([k,l])=>'<div class="kt-status-tile kt-'+k+'"><strong>'+N(h[k])+'</strong><small>'+l+'</small></div>').join('')+'</div><div class="kt-gauge" style="--v:'+(avg??0)+'"><strong>'+(avg===null?'—':N(avg)+'٪')+'</strong><small>میانگین '+N(ps.length)+' هدفِ سنجیده</small></div></div>';}
function kpiCards(d,uid,kpis){return '<div class="kt-section"><h2>📊 شاخص‌های عملکرد <small>'+N(kpis.length)+'</small></h2><button type="button" class="kt-primary" data-p-action="kpi" data-p-id="'+X(uid)+'">＋ افزودن KPI</button></div><div class="kt-kpis">'+(kpis.length?kpis.map(k=>{let h=khealth(k),hist=d.kpiHistory.filter(x=>x.kpiId===k.id).sort((a,b)=>String(b.at).localeCompare(String(a.at))),prev=hist[1]?.value,delta=num(prev)!==null&&num(k.current)!==null?Number(k.current)-Number(prev):null;
 return '<a class="kt-kpi kt-'+h[0]+'" href="#kpis/'+url(k.id)+'"><b>'+X(k.name)+'</b><strong>'+(num(k.current)===null?'—':N(k.current))+' <small>'+X(k.unit)+'</small></strong><div>'+badge(h)+'<span>هدف: '+N(k.target)+'</span></div><footer><span>'+(delta===null?'تغییر: بدون سابقه':'تغییر: '+(delta>=0?'↗ ':'↘ ')+N(Math.abs(delta)))+'</span><span>'+date(hist[0]?.at)+'</span></footer></a>'}).join(''):'<p class="kt-empty">شاخصی برای این واحد ثبت نشده است.</p>')+'</div>';}
function rowResult(g,d){let body='';
 if(f.results!=='initiative')body+=(g.krs||[]).map(k=>{let h=history(d,k.id)[0],s=({ 'on-track':['on','روی مسیر'],attention:['attention','نیازمند توجه'],'off-track':['off','خارج از مسیر']})[h?.confidence||k.confidence]||['none','بدون وضعیت'];return '<div class="kt-result"><div class="kt-result-title"><span>↗ KR</span><a href="#results/'+url(k.id)+'">'+X(k.text)+'</a><small>'+person(k.owner,d)+'</small></div><div class="kt-result-measure"><span>'+N(k.current)+' / '+N(k.target)+' '+X(k.unit)+'</span>'+badge(s)+'<b>'+(pct(k)===null?'—':N(pct(k))+'٪')+'</b><button type="button" data-p-action="checkin" data-p-id="'+X(k.id)+'">ثبت پیشرفت</button></div></div>'}).join('');
 if(f.results!=='kr')body+=d.initiatives.filter(i=>i.objectiveId===g.id).map(i=>'<div class="kt-result"><div class="kt-result-title"><span>🚀 ابتکار</span><a href="#projects/'+url(i.id)+'">'+X(i.title)+'</a><small>'+person(i.owner,d)+'</small></div><div class="kt-result-measure">'+badge([i.status==='done'?'on':'none',({done:'تکمیل',blocked:'متوقف','in-progress':'در حال اجرا',planned:'برنامه‌ریزی'})[i.status]||'نامشخص'])+'<a href="#projects/'+url(i.id)+'">جزئیات</a></div></div>').join('');
 return '<div class="kt-results">'+(body||'<p class="kt-empty">نتیجه‌ای در این فیلتر ثبت نشده است.</p>')+'<div class="kt-result-foot"><button data-p-action="kr" data-p-id="'+X(g.id)+'">＋ افزودن نتیجه کلیدی</button><a href="#goals/'+url(g.id)+'">مدیریت ابتکارات و هدف</a></div></div>';}
function goalCard(g,d,m){let h=health(g,d),p=progress(g),c=m.get(g.id),open=f.show&&f.expanded.has(g.id);
 return '<article class="kt-okr kt-'+h[0]+'"><div class="kt-okr-top"><button type="button" data-kt-expand="'+X(g.id)+'" aria-expanded="'+open+'">'+(open?'−':'＋')+'</button><div><a class="kt-okr-title" href="#goals/'+url(g.id)+'">'+X(g.objective||'هدف بدون عنوان')+'</a><small>'+person(g.owner,d)+' · '+X(c?.name||'دوره تعیین نشده')+'</small></div>'+badge(h)+'<button type="button" title="ویرایش هدف و وضعیت" data-p-action="goal-edit" data-p-id="'+X(g.id)+'">⋮</button></div><div class="kt-okr-meta"><b>'+(p===null?'—':N(p)+'٪')+'</b><span class="kt-bar"><i style="width:'+(p??0)+'%"></i></span><small>'+N((g.krs||[]).length)+' KR · '+N(d.initiatives.filter(x=>x.objectiveId===g.id).length)+' ابتکار</small><a href="#goals/'+url(g.id)+'">جزئیات</a></div>'+ (open?rowResult(g,d):'')+'</article>';}
function controls(d){const opt=(arr,val)=>arr.map(([v,l])=>'<option value="'+X(v)+'" '+(v===val?'selected':'')+'>'+X(l)+'</option>').join('');
 return '<div class="kt-controls"><div class="kt-lifecycle" role="tablist">'+[['active','فعال'],['draft','پیش‌نویس'],['closed','مختومه'],['all','همه']].map(([v,l])=>'<button type="button" role="tab" aria-selected="'+(v===f.status)+'" data-kt-status="'+v+'" class="'+(v===f.status?'active':'')+'">'+l+'</button>').join('')+'</div><div class="kt-filters"><select data-kt-time aria-label="دوره">'+opt([['all','همه دوره‌ها'],...d.cycles.map(c=>[c.id,c.name||date(c.start)])],f.time)+'</select><select data-kt-results aria-label="نوع نتایج">'+opt([['all','همه نتایج'],['kr','نتایج کلیدی'],['initiative','ابتکارات']],f.results)+'</select><select data-kt-sort aria-label="مرتب‌سازی">'+opt([['latest','آخرین به‌روزرسانی'],['title','عنوان'],['progress','پیشرفت'],['health','سلامت'],['time','دوره'],['owner','مسئول']],f.sort)+'</select><input data-kt-q type="search" value="'+X(f.q)+'" placeholder="جست‌وجوی اهداف"><button data-kt-toggle type="button">'+(f.show?'پنهان‌کردن نتایج':'نمایش نتایج')+'</button><button data-kt-export="csv" type="button">⬇ CSV / Excel</button><button data-kt-export="pdf" type="button">🖨 PDF</button></div></div>';}
function goals(d,uid,own){let r=filtered(d,uid);return kpiCards(d,uid,own.kpis)+'<div class="kt-section"><h2>🎯 اهداف و نتایج کلیدی <small>'+N(r.goals.length)+'</small></h2><button class="kt-primary" type="button" data-p-action="goal" data-p-id="'+X(uid)+'">＋ افزودن OKR</button></div>'+controls(d)+(r.goals.length?'<div class="kt-okr-list">'+r.goals.map(g=>goalCard(g,d,r.m)).join('')+'</div>':'<p class="kt-empty">هدف منطبق با این فیلتر یافت نشد.</p>')+'<p class="kt-note">ثبت هدف از فرم اصلی سامانه انجام می‌شود. بعد از ذخیره، KR و ابتکار را به همان هدف اضافه کنید؛ رکورد موازی ساخته نمی‌شود.</p>';}
function members(d,uid,own){let unit=findUnit(d,uid),members=d.people.filter(p=>uid==='company'||p.teamId===uid||unit.descendantIds?.includes(p.teamId)),keys=new Set(members.flatMap(p=>[p.id,p.name,p.email])),assigned=[...new Set([...own.goals.map(g=>g.owner),...own.goals.flatMap(g=>(g.krs||[]).map(k=>k.owner)),...own.kpis.map(k=>k.owner)].filter(Boolean))],missing=assigned.filter(x=>!keys.has(x));
 return '<div class="kt-section"><h2>👥 اعضای ثبت‌شده <small>'+N(members.length)+'</small></h2><button class="kt-primary" type="button" data-p-action="person" data-p-id="'+X(uid)+'">＋ افزودن عضو</button></div><div class="kt-members">'+(members.length?members.map(p=>'<a class="kt-member" href="#people/'+url(p.id)+'">'+avatar(p)+'<div><b>'+X(p.name)+'</b><small>'+X(p.title||'سمت ثبت نشده')+'</small><small>'+N(own.goals.filter(g=>[p.id,p.email,p.name].includes(g.owner)).length)+' هدف · '+N(own.goals.flatMap(g=>g.krs||[]).filter(k=>[p.id,p.email,p.name].includes(k.owner)).length)+' KR</small></div></a>').join(''):'<p class="kt-empty">عضوی برای این واحد ثبت نشده است.</p>')+'</div>'+(missing.length?'<div class="kt-note"><b>⚠️ مسئولان فاقد پرونده عضویت</b><p>'+missing.map(X).join('، ')+'</p></div>':'')+'<p class="kt-note">پرونده عضو در نسخه عمومی، حساب کاربری و مجوز مدیریتی واقعی ایجاد نمی‌کند. این بخش فقط عضویت ثبت‌شده در داده‌های سازمان را نمایش می‌دهد.</p>';}
function checkins(d,own){let items=own.goals.flatMap(g=>(g.krs||[]).map(k=>({g,k,h:history(d,k.id)[0]}))),stale=items.filter(x=>!x.h||Date.now()-Date.parse(x.h.at)>14*864e5);
 return '<div class="kt-section"><h2>🗒️ ثبت پیشرفت</h2><span class="kt-callout">'+N(stale.length)+' نتیجه بدون ثبت معتبر در ۱۴ روز اخیر</span></div><div class="kt-checks">'+(items.length?items.map(({g,k,h})=>'<article class="kt-check"><div><a href="#results/'+url(k.id)+'"><b>'+X(k.text)+'</b></a><small>'+X(g.objective)+'</small>'+person(k.owner,d)+'</div><div><strong>'+(pct(k)===null?'—':N(pct(k))+'٪')+'</strong><small>آخرین ثبت: '+date(h?.at||k.lastUpdate)+'</small><small>'+X(h?.by||'')+' · '+X(h?.note||'بدون یادداشت ثبت‌شده')+'</small><button class="kt-primary" data-p-action="checkin" data-p-id="'+X(k.id)+'" type="button">ثبت Check-in</button></div></article>').join(''):'<p class="kt-empty">هنوز نتیجه کلیدی برای ثبت پیشرفت وجود ندارد.</p>')+'</div>';}
function performance(d,own){let active=own.goals.filter(g=>g.status==='active'),valid=active.map(progress).filter(x=>x!==null),avg=valid.length?Math.round(valid.reduce((a,b)=>a+b,0)/valid.length):null,h1=own.kpis.filter(k=>khealth(k)[0]==='on').length,h2=own.kpis.filter(k=>khealth(k)[0]==='attention').length,h3=own.kpis.length-h1-h2;
 return '<div class="kt-section"><h2>📈 عملکرد واحد</h2><small>این گزارش برای پایش تیم است، نه ارزیابی عملکرد فردی</small></div><div class="kt-performance"><div class="kt-perf-metrics">'+[['میانگین اهداف سنجیده',avg===null?'—':N(avg)+'٪'],['اهداف مختومه',N(own.goals.filter(x=>x.status==='closed').length)],['شاخص مطلوب',N(h1)],['شاخص نامطلوب',N(h2)],['KPI بدون داده',N(h3)]].map(([a,b])=>'<div><strong>'+b+'</strong><span>'+a+'</span></div>').join('')+'</div><div class="kt-perf-block"><h3>🎯 پیشرفت اهداف فعال</h3>'+(active.length?active.map(g=>'<a class="kt-perf-row" href="#goals/'+url(g.id)+'"><span>'+X(g.objective)+'</span>'+badge(health(g,d))+'<strong>'+(progress(g)===null?'—':N(progress(g))+'٪')+'</strong><span class="kt-bar"><i style="width:'+(progress(g)??0)+'%"></i></span></a>').join(''):'<p class="kt-empty">هدف فعال موجود نیست.</p>')+'</div><div class="kt-perf-block"><h3>🕒 آخرین Check-inها</h3>'+d.history.filter(h=>active.some(g=>(g.krs||[]).some(k=>k.id===h.krId))).sort((a,b)=>String(b.at).localeCompare(String(a.at))).slice(0,10).map(h=>'<div class="kt-perf-history"><time>'+date(h.at)+'</time><a href="#results/'+url(h.krId)+'">'+X(active.flatMap(g=>g.krs||[]).find(k=>k.id===h.krId)?.text||'KR')+'</a><strong>'+N(h.current)+'</strong></div>').join('')+'</div></div><p class="kt-note">میانگین فقط از KRهای دارای Baseline، Current و Target معتبر محاسبه می‌شود. برای مقایسه واقعی دوره‌ای به داده تاریخی کافی نیاز است.</p>';}
function render(d,uid='company',tab='goals'){
 if(!d)return '<p class="kt-empty">فضای کاری هنوز آماده نیست.</p>';uid=uid||'company';if(uid!=='company'&&!d.units.some(x=>x.id===uid))return '<p class="kt-empty">واحد پیدا نشد. <a href="#team/company/goals">بازگشت</a></p>';
 tab=['goals','members','checkins','performance'].includes(tab)?tab:'goals';const t=findUnit(d,uid),own=scoped(d,uid),membersCount=d.people.filter(p=>uid==='company'||p.teamId===uid||t.descendantIds?.includes(p.teamId)).length;
 return '<section class="kt-shell" dir="rtl">'+teamNav(d,uid)+'<main class="kt-main"><header class="kt-header"><div class="kt-heading"><i>'+X(t.name.slice(0,1))+'</i><div><small>🏢 داشبورد اهداف واحدهای سازمانی</small><h1>'+X(t.name)+'</h1><span>اهداف، شاخص‌ها، اعضا و پیشرفت</span></div></div><div class="kt-links"><a href="#map">🧭 نقشه راهبرد</a><a href="#organization/'+url(uid)+'/overview">پرونده سازمانی</a></div></header>'+score(d,own.goals)+'<nav class="kt-tabs" role="tablist">'+[['goals','🎯 اهداف'],['members','👥 اعضا '+N(membersCount)],['checkins','🗒️ ثبت پیشرفت'],['performance','📈 عملکرد']].map(([key,title])=>'<a role="tab" aria-selected="'+(key===tab)+'" class="'+(key===tab?'active':'')+'" href="#team/'+url(uid)+'/'+key+'">'+title+'</a>').join('')+'</nav><div class="kt-content">'+(tab==='goals'?goals(d,uid,own):tab==='members'?members(d,uid,own):tab==='checkins'?checkins(d,own):performance(d,own))+'</div><footer class="kt-footer">بخش‌های مرتبط: <a href="#organization/'+url(uid)+'/projects">پروژه‌ها</a><a href="#organization/'+url(uid)+'/sessions">جلسات</a><a href="#organization/'+url(uid)+'/resources">اسناد</a></footer></main></section>';
}
function toCSV(d,uid){let rows=[['Type','Unit','Objective/KPI','Lifecycle','Health','Owner','Timeframe','Progress','Key Result','Baseline','Current','Target','Unit','Initiative']],r=filtered(d,uid),own=scoped(d,uid);
 own.kpis.forEach(k=>rows.push(['KPI',findUnit(d,uid).name,k.name,'',khealth(k)[1],k.owner,'','', '', '',k.current,k.target,k.unit,'']));
 r.goals.forEach(g=>{let c=r.m.get(g.id);rows.push(['Objective',findUnit(d,uid).name,g.objective,g.status,health(g,d)[1],g.owner,c?.name||'',progress(g)??'','','','','','','']);if(f.show&&f.results!=='initiative')(g.krs||[]).forEach(k=>rows.push(['KR','',g.objective,g.status,'',k.owner,c?.name||'',pct(k)??'',k.text,k.baseline,k.current,k.target,k.unit,'']));if(f.show&&f.results!=='kr')d.initiatives.filter(i=>i.objectiveId===g.id).forEach(i=>rows.push(['Initiative','',g.objective,i.status,'',i.owner,c?.name||'','','','','','','',i.title]))});
 const quote=v=>{let s=String(v??'');if(/^\s*[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};
 return '\uFEFF'+rows.map(row=>row.map(quote).join(',')).join('\r\n');
}
function refresh(selector){if(!window.KishTeamBridge)return;let parts=decodeURIComponent(location.hash.slice(1)).split('/');if(parts[0]!=='team')return;const body=document.getElementById('platformBody');if(!body)return;const pos=window.scrollY;body.innerHTML='<div class="p-page">'+render(window.KishTeamBridge.snapshot(),parts[1]||'company',parts[2]||'goals')+'</div>';if(selector){const q=body.querySelector(selector);q?.focus();if(q?.setSelectionRange&&q.type==='search')q.setSelectionRange(q.value.length,q.value.length)}window.scrollTo(0,pos)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-kt-expand]');if(b){let id=b.dataset.ktExpand;f.expanded.has(id)?f.expanded.delete(id):f.expanded.add(id);refresh();return}b=e.target.closest('[data-kt-toggle]');if(b){f.show=!f.show;refresh();return}b=e.target.closest('[data-kt-status]');if(b){f.status=b.dataset.ktStatus;refresh();return}b=e.target.closest('[data-kt-export]');if(b&&window.KishTeamBridge){if(b.dataset.ktExport==='pdf'){window.print();return}let d=window.KishTeamBridge.snapshot(),uid=decodeURIComponent(location.hash.slice(1)).split('/')[1]||'company',blob=new Blob([toCSV(d,uid)],{type:'text/csv;charset=utf-8'}),u1=URL.createObjectURL(blob),a=document.createElement('a');a.href=u1;a.download='Kish-Team-'+uid.replace(/[^a-z0-9_-]/gi,'_')+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u1),1500)}});
document.addEventListener('change',e=>{let x=e.target;if(x.matches('[data-kt-time]'))f.time=x.value;else if(x.matches('[data-kt-results]'))f.results=x.value;else if(x.matches('[data-kt-sort]'))f.sort=x.value;else return;refresh()});
let tid;document.addEventListener('input',e=>{let k=e.target.matches('[data-kt-q]')?'q':e.target.matches('[data-kt-teamq]')?'teamq':null;if(!k)return;f[k]=e.target.value;clearTimeout(tid);tid=setTimeout(()=>refresh('[data-kt-'+k+']'),140)});
window.KishTeamView={render,refresh,filtered,pct,progress,health,khealth,toCSV};})();
